    public static func ==(lhs: DayCount, rhs: DayCount) -> Bool {
        if lhs.dayStart != rhs.dayStart {
            return false
        }
        if lhs.count != rhs.count {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(dayStart)
        hasher.combine(count)
    }
}



